#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat() : name("无名"), fish(0) {}
    Cat(string n, int f) : name(n), fish(f) {}

    void show() const {
        cout << name << "：" << fish << " 条" << endl;
    }
};

int main() {
    int a = 0;
    cin >> a;

    Cat c1;
    Cat c2("{name}", a);
    c1.show();
    c2.show();
    return 0;
}
